mapper.select:
SELECT lr.*, s.student_no, s.name as student_name, c.class_name, co.course_name, t.name as approver_name FROM leave_request lr LEFT JOIN student s ON lr.student_id = s.id LEFT JOIN class c ON s.class_id = c.class_code LEFT JOIN course_arrangement ca ON lr.course_arrangement_id = ca.id LEFT JOIN course co ON ca.course_id = co.id LEFT JOIN teacher t ON lr.approver_id = t.id
AND lr.student_id = #{studentId}
AND ca.teacher_id = #{teacherId}
AND lr.status = #{status}
ORDER BY lr.create_time DESC
